// utils/secretRotation.js
class SecretRotator {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.activeSecrets = new Map();
    this.rotationInterval = 24 * 60 * 60 * 1000; // 24 hours
  }

  async initialize() {
    await this.rotateSecrets();
    setInterval(() => this.rotateSecrets(), this.rotationInterval);
  }

  async rotateSecrets() {
    try {
      const newSecrets = await this.fetchSecrets();
      this.activeSecrets.set(Date.now(), newSecrets);
      this.cleanupOldSecrets();
    } catch (error) {
      console.error('Secret rotation failed:', error);
    }
  }

  async fetchSecrets() {
    // Fetch from secure source
    const response = await this.secretsManager.getSecretValue({
      SecretId: process.env.SECRET_NAME
    });
    return JSON.parse(response.SecretString);
  }

  cleanupOldSecrets() {
    const cutoff = Date.now() - (2 * this.rotationInterval);
    for (const [timestamp] of this.activeSecrets) {
      if (timestamp < cutoff) {
        this.activeSecrets.delete(timestamp);
      }
    }
  }

  getCurrentSecrets() {
    const latestTimestamp = Math.max(...Array.from(this.activeSecrets.keys()));
    return this.activeSecrets.get(latestTimestamp);
  }
}
