```javascript
// secure-secrets-loader.js
class SecureSecretLoader {
  constructor() {
    this.secretsCache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(name) {
    const cached = this.secretsCache.get(name);
    if (cached && (Date.now() - cached.timestamp) < this.cacheTTL) {
      return cached.value;
    }

    const value = await this.fetchSecret(name);
    this.secretsCache.set(name, {
      value,
      timestamp: Date.now()
    });

    return value;
  }

  async fetchSecret(name) {
    switch (process.env.SECRETS_BACKEND) {
      case 'aws':
        return this.fetchFromAWS(name);
      case 'vault':
        return this.fetchFromVault(name);
      case 'gcp':
        return this.fetchFromGCP(name);
      default:
        return this.fetchFromLocal(name);
    }
  }

  async fetchFromAWS(name) {
    const { SecretsManager } = require('aws-sdk');
    const client = new SecretsManager({
      region: process.env.AWS_REGION
    });

    const response = await client.getSecretValue({
      SecretId: `/${process.env.APP_ENV}/${name}`
    }).promise();

    return JSON.parse(response.SecretString);
  }

  // ... other implementations
}

module.exports = new SecureSecretLoader();
```

