```javascript
// migrate-secrets.js
const fs = require('fs');
const { SecretsManager } = require('aws-sdk');

async function migrateToSecretsManager() {
  const secretsManager = new SecretsManager();
  const envContent = fs.readFileSync('.env.production', 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    if (line && !line.startsWith('#')) {
      const [key, value] = line.split('=', 2);
      if (key && value) {
        envVars[key.trim()] = value.trim();
      }
    }
  });

  // Create secret in AWS Secrets Manager
  await secretsManager.createSecret({
    Name: 'app/production',
    SecretString: JSON.stringify(envVars),
    Description: 'Application secrets for production environment',
    Tags: [
      { Key: 'Environment', Value: 'production' },
      { Key: 'Application', Value: 'my-app' }
    ]
  }).promise();

  console.log('Secrets migrated successfully');
  console.log('REMEMBER: Delete .env.production file after verification');
}
```

