/**
 * Secure Secrets Loader
 * 
 * Centralized secrets management for Node.js applications
 * Supports multiple backends: AWS Secrets Manager, HashiCorp Vault, local files
 * 
 * Usage:
 *   const secrets = await loadSecrets();
 *   const dbPassword = secrets.database.password;
 * 
 * Configuration via environment variables:
 *   SECRETS_BACKEND=aws|vault|gcp|local
 *   SECRETS_REGION=us-east-1 (AWS)
 *   VAULT_ADDR=https://vault.example.com
 *   GCP_PROJECT_ID=my-project
 */

const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');

class SecretsLoader {
  constructor(options = {}) {
    this.options = {
      backend: process.env.SECRETS_BACKEND || 'local',
      cacheTTL: parseInt(process.env.SECRETS_CACHE_TTL) || 300000, // 5 minutes
      ...options
    };

    this.cache = new Map();
    this.cacheTimestamps = new Map();
    this.logger = this.createLogger();
  }

  createLogger() {
    return {
      info: (msg, data) => console.log(`[SecretsLoader] ${msg}`, data || ''),
      warn: (msg, data) => console.warn(`[SecretsLoader] ${msg}`, data || ''),
      error: (msg, error) => console.error(`[SecretsLoader] ${msg}`, error),
      debug: (msg, data) => {
        if (process.env.NODE_ENV !== 'production') {
          console.debug(`[SecretsLoader] ${msg}`, data || '');
        }
      }
    };
  }

  async get(secretName, options = {}) {
    const { bypassCache = false } = options;

    // Check cache first
    if (!bypassCache && this.isCacheValid(secretName)) {
      this.logger.debug(`Cache hit for secret: ${secretName}`);
      return this.cache.get(secretName);
    }

    this.logger.debug(`Loading secret: ${secretName}`);

    let secretValue;
    try {
      switch (this.options.backend) {
        case 'aws':
          secretValue = await this.loadFromAWS(secretName);
          break;
        case 'vault':
          secretValue = await this.loadFromVault(secretName);
          break;
        case 'gcp':
          secretValue = await this.loadFromGCP(secretName);
          break;
        case 'encrypted':
          secretValue = await this.loadFromEncryptedFile(secretName);
          break;
        case 'local':
        default:
          secretValue = await this.loadFromLocal(secretName);
          break;
      }

      // Cache the result
      this.cache.set(secretName, secretValue);
      this.cacheTimestamps.set(secretName, Date.now());

      this.logger.info(`Successfully loaded secret: ${secretName}`);
      return secretValue;

    } catch (error) {
      this.logger.error(`Failed to load secret: ${secretName}`, error);
      throw error;
    }
  }

  async getAll(secretPath) {
    try {
      switch (this.options.backend) {
        case 'aws':
          return await this.loadAllFromAWS(secretPath);
        case 'vault':
          return await this.loadAllFromVault(secretPath);
        case 'local':
          return await this.loadAllFromLocal(secretPath);
        default:
          throw new Error(`Bulk loading not supported for backend: ${this.options.backend}`);
      }
    } catch (error) {
      this.logger.error(`Failed to load secrets from path: ${secretPath}`, error);
      throw error;
    }
  }

  async loadFromAWS(secretName) {
    // Lazy load AWS SDK
    const { SecretsManager } = require('aws-sdk');

    const client = new SecretsManager({
      region: process.env.AWS_REGION || process.env.SECRETS_REGION || 'us-east-1',
      ...(process.env.AWS_ACCESS_KEY_ID && {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      })
    });

    const secretId = this.getSecretId(secretName);

    try {
      const response = await client.getSecretValue({ SecretId: secretId }).promise();

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        return buff.toString('utf-8');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretId}`);
      }
      throw error;
    }
  }

  async loadFromVault(secretName) {
    // Lazy load node-vault
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    const secretPath = `secret/data/${this.getSecretId(secretName)}`;

    try {
      const response = await vault.read(secretPath);
      return response.data.data;
    } catch (error) {
      if (error.statusCode === 404) {
        throw new Error(`Secret not found: ${secretPath}`);
      }
      throw error;
    }
  }

  async loadFromGCP(secretName) {
    // Lazy load GCP Secret Manager
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

    const client = new SecretManagerServiceClient();
    const projectId = process.env.GCP_PROJECT_ID;
    const secretId = this.getSecretId(secretName);

    const name = `projects/${projectId}/secrets/${secretId}/versions/latest`;

    try {
      const [version] = await client.accessSecretVersion({ name });
      return version.payload.data.toString('utf8');
    } catch (error) {
      if (error.code === 5) { // NOT_FOUND
        throw new Error(`Secret not found: ${secretId}`);
      }
      throw error;
    }
  }

  async loadFromEncryptedFile(secretName) {
    const encryptionKey = process.env.ENCRYPTION_KEY;
    if (!encryptionKey) {
      throw new Error('ENCRYPTION_KEY environment variable is required for encrypted secrets');
    }

    const filePath = path.join(process.cwd(), 'secrets', `${secretName}.encrypted`);

    try {
      const encrypted = await fs.readFile(filePath, 'utf8');
      const decipher = crypto.createDecipher('aes-256-gcm', encryptionKey);

      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      return JSON.parse(decrypted);
    } catch (error) {
      if (error.code === 'ENOENT') {
        throw new Error(`Encrypted secret file not found: ${filePath}`);
      }
      throw error;
    }
  }

  async loadFromLocal(secretName) {
    // For local development, fall back to environment variables
    const envVarName = secretName.toUpperCase().replace(/-/g, '_');

    if (process.env[envVarName]) {
      try {
        // Try to parse as JSON first
        return JSON.parse(process.env[envVarName]);
      } catch {
        // If not valid JSON, return as string
        return process.env[envVarName];
      }
    }

    // Fall back to .env.local file (development only)
    if (process.env.NODE_ENV === 'development') {
      try {
        const dotenv = require('dotenv');
        const envLocal = dotenv.config({ path: '.env.local' });

        if (envLocal.parsed && envLocal.parsed[envVarName]) {
          return envLocal.parsed[envVarName];
        }
      } catch (error) {
        // Silently ignore if .env.local doesn't exist
      }
    }

    throw new Error(`Secret not found: ${secretName} (tried env var: ${envVarName})`);
  }

  async loadAllFromAWS(secretPath) {
    const { SecretsManager } = require('aws-sdk');

    const client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await client.listSecrets({}).promise();
      const secrets = {};

      for (const secret of response.SecretList) {
        if (secret.Name.startsWith(secretPath)) {
          const secretValue = await this.get(secret.Name);
          const key = secret.Name.replace(`${secretPath}/`, '');
          secrets[key] = secretValue;
        }
      }

      return secrets;
    } catch (error) {
      throw error;
    }
  }

  getSecretId(secretName) {
    const env = process.env.NODE_ENV || 'development';
    const appName = process.env.APP_NAME || 'app';

    if (secretName.includes('/')) {
      return secretName; // Full path provided
    }

    return `${appName}/${env}/${secretName}`;
  }

  isCacheValid(secretName) {
    const timestamp = this.cacheTimestamps.get(secretName);
    if (!timestamp) return false;

    return (Date.now() - timestamp) < this.options.cacheTTL;
  }

  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
      this.cacheTimestamps.delete(secretName);
    } else {
      this.cache.clear();
      this.cacheTimestamps.clear();
    }
  }

  /**
   * Helper to load all required secrets for the application
   */
  async loadApplicationSecrets() {
    const requiredSecrets = [
      'database',
      'jwt-secret',
      'api-keys',
      'aws-credentials'
    ];

    const secrets = {};
    const errors = [];

    for (const secretName of requiredSecrets) {
      try {
        secrets[secretName] = await this.get(secretName);
      } catch (error) {
        if (process.env.NODE_ENV === 'production') {
          errors.push(`Missing required secret: ${secretName}`);
        } else {
          // In development, use defaults or throw
          this.logger.warn(`Optional secret not found in development: ${secretName}`);
        }
      }
    }

    if (errors.length > 0 && process.env.NODE_ENV === 'production') {
      throw new Error(`Missing required secrets:\n${errors.join('\n')}`);
    }

    return secrets;
  }
}

// Singleton instance
let instance = null;

function getSecretsLoader(options) {
  if (!instance) {
    instance = new SecretsLoader(options);
  }
  return instance;
}

// Convenience function for quick secret access
async function getSecret(secretName, options) {
  const loader = getSecretsLoader();
  return loader.get(secretName, options);
}

// Convenience function for loading all app secrets
async function loadAppSecrets() {
  const loader = getSecretsLoader();
  return loader.loadApplicationSecrets();
}

module.exports = {
  SecretsLoader,
  getSecretsLoader,
  getSecret,
  loadAppSecrets
};

/**
 * Example configuration using secure secrets loader
 * 
 * This shows how to properly structure application configuration
 * with secure secrets management.
 */

const { getSecretsLoader, loadAppSecrets } = require('./secrets-loader');

class ApplicationConfig {
  constructor() {
    this.config = null;
    this.secretsLoader = getSecretsLoader();
  }

  async initialize() {
    if (this.config) {
      return this.config;
    }

    // Load all secrets
    const secrets = await loadAppSecrets();

    // Build configuration object
    this.config = Object.freeze({
      // Environment
      env: process.env.NODE_ENV || 'development',
      isProduction: process.env.NODE_ENV === 'production',
      isDevelopment: process.env.NODE_ENV === 'development' || !process.env.NODE_ENV,
      isTest: process.env.NODE_ENV === 'test',

      // Server
      port: parseInt(process.env.PORT) || 3000,
      host: process.env.HOST || 'localhost',

      // Database (from secrets)
      database: {
        url: secrets.database?.url || process.env.DATABASE_URL,
        ...(secrets.database || {})
      },

      // API Keys (from secrets)
      apiKeys: {
        stripe: secrets['api-keys']?.stripe || process.env.STRIPE_SECRET_KEY,
        anthropic: secrets['api-keys']?.anthropic || process.env.ANTHROPIC_API_KEY,
        ...(secrets['api-keys'] || {})
      },

      // AWS Credentials (from secrets)
      aws: secrets['aws-credentials'] || {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      },

      // JWT (from secrets)
      jwt: {
        secret: secrets['jwt-secret'] || process.env.JWT_SECRET,
        expiresIn: '24h'
      },

      // Security
      security: {
        corsOrigins: process.env.CORS_ORIGINS ? 
          process.env.CORS_ORIGINS.split(',') : 
          ['http://localhost:3000', 'http://localhost:3001'],
        rateLimit: {
          windowMs: 15 * 60 * 1000, // 15 minutes
          max: process.env.NODE_ENV === 'production' ? 100 : 1000
        }
      },

      // Features flags
      features: {
        enableGraphQL: process.env.ENABLE_GRAPHQL === 'true',
        enableWebhooks: process.env.ENABLE_WEBHOOKS === 'true',
        maintenanceMode: process.env.MAINTENANCE_MODE === 'true'
      },

      // Logging
      logging: {
        level: process.env.LOG_LEVEL || 'info',
        logfireToken: secrets.logging?.token || process.env.LOGFIRE_TOKEN
      }
    });

    // Validate configuration
    this.validateConfig();

    return this.config;
  }

  validateConfig() {
    const errors = [];

    // Production validation
    if (this.config.isProduction) {
      if (!this.config.database.url) {
        errors.push('DATABASE_URL is required in production');
      }

      if (!this.config.jwt.secret) {
        errors.push('JWT_SECRET is required in production');
      }

      if (this.config.jwt.secret === 'secret' || this.config.jwt.secret === 'change-me') {
        errors.push('JWT_SECRET must not use default value in production');
      }
    }

    // Warn for development
    if (this.config.isDevelopment) {
      if (this.config.database.url && this.config.database.url.includes('production')) {
        console.warn('⚠️  WARNING: Using production database in development environment');
      }

      if (this.config.apiKeys.stripe && this.config.apiKeys.stripe.startsWith('sk_live_')) {
        console.warn('⚠️  WARNING: Using live Stripe key in development environment');
      }
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }
  }

  // Get individual config values
  get(key) {
    if (!this.config) {
      throw new Error('Configuration not initialized. Call initialize() first.');
    }

    const keys = key.split('.');
    let value = this.config;

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return undefined;
      }
    }

    return value;
  }

  // Get entire config
  getAll() {
    if (!this.config) {
      throw new Error('Configuration not initialized. Call initialize() first.');
    }
    return this.config;
  }

  // Clear config (useful for testing)
  clear() {
    this.config = null;
    this.secretsLoader.clearCache();
  }
}

// Singleton instance
let configInstance = null;

async function getConfig() {
  if (!configInstance) {
    configInstance = new ApplicationConfig();
    await configInstance.initialize();
  }
  return configInstance;
}

// Convenience functions
async function initConfig() {
  return getConfig();
}

function getConfigValue(key) {
  if (!configInstance) {
    throw new Error('Configuration not initialized. Call initConfig() first.');
  }
  return configInstance.get(key);
}

module.exports = {
  ApplicationConfig,
  getConfig,
  initConfig,
  getConfigValue
};

/**
 * Secure Express.js Application with Secrets Management
 * 
 * This version demonstrates proper secrets handling using:
 * 1. Secure secrets loader
 * 2. Environment-based configuration
 * 3. Defense in depth
 */

// First, load configuration before anything else
require('./config-example').initConfig().then(async () => {
  const { getConfig } = require('./config-example');
  const config = await getConfig();

  const express = require('express');
  const helmet = require('helmet');
  const cors = require('cors');
  const rateLimit = require('express-rate-limit');
  const morgan = require('morgan');
  const jwt = require('jsonwebtoken');
  const { body, validationResult } = require('express-validator');

  const app = express();

  // ========================
  // SECURITY MIDDLEWARE STACK
  // ========================

  // 1. Security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
        connectSrc: ["'self'"],
        fontSrc: ["'self'"],
        objectSrc: ["'none'"],
        mediaSrc: ["'self'"],
        frameSrc: ["'none'"],
      },
    },
    hsts: config.isProduction ? {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    } : false
  }));

  // 2. CORS configuration (from config)
  app.use(cors({
    origin: config.security.corsOrigins,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400
  }));

  // 3. Rate limiting (from config)
  const limiter = rateLimit({
    windowMs: config.security.rateLimit.windowMs,
    max: config.security.rateLimit.max,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false
  });
  app.use(limiter);

  // 4. Request parsing with limits
  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ limit: '1mb', extended: true }));

  // 5. Request logging
  if (!config.isTest) {
    app.use(morgan(config.isProduction ? 'combined' : 'dev', {
      skip: (req) => req.path === '/health'
    }));
  }

  // ========================
  // AUTHENTICATION
  // ========================

  const authenticate = (req, res, next) => {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ 
        error: 'Authentication required',
        message: 'Include Authorization: Bearer <token> header'
      });
    }

    const token = authHeader.substring(7);

    try {
      const decoded = jwt.verify(token, config.jwt.secret);
      req.user = decoded;
      next();
    } catch (error) {
      return res.status(403).json({ 
        error: 'Invalid token',
        message: 'Token is expired or invalid'
      });
    }
  };

  // ========================
  // ROUTES
  // ========================

  // Public health endpoint (no sensitive info)
  app.get('/health', (req, res) => {
    res.set('Cache-Control', 'no-store');
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: config.env,
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  });

  // Protected users endpoint
  app.get('/users', 
