// Secure secrets management with multi-layer fallback strategy
// Supports: AWS Secrets Manager, Azure Key Vault, Environment Variables, Local files

const fs = require('fs').promises;
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecureSecretsManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
    this.secretsSource = 'unknown';
    this.rotationWatchers = new Map();
  }

  /**
   * Initialize secrets with multi-layer fallback strategy
   * Priority: Cloud Secrets Manager > Environment Variables > Local .env file
   */
  async initialize() {
    try {
      // Try cloud secrets manager first
      if (await this.tryCloudSecretsManager()) {
        this.secretsSource = 'cloud-secrets-manager';
        console.log('🔑 Using cloud secrets manager');
      }
      // Fallback to environment variables
      else if (await this.loadFromEnvironment()) {
        this.secretsSource = 'environment-variables';
        console.log('🔑 Using environment variables');
      }
      // Final fallback to local .env file (development only)
      else if (process.env.NODE_ENV !== 'production' && await this.loadFromEnvFile()) {
        this.secretsSource = 'local-env-file';
        console.warn('⚠️  Using local .env file - NOT RECOMMENDED for production');
      } else {
        throw new Error('No secrets source available');
      }

      // Validate required secrets
      this.validateRequiredSecrets();

      // Start secret rotation watchers (for cloud secrets)
      if (this.secretsSource === 'cloud-secrets-manager') {
        this.startRotationWatchers();
      }

      this.initialized = true;
      console.log(`✅ Secrets initialized from: ${this.secretsSource}`);

    } catch (error) {
      console.error('❌ Failed to initialize secrets:', error.message);
      throw error;
    }
  }

  /**
   * Try to load secrets from AWS Secrets Manager
   */
  async tryCloudSecretsManager() {
    try {
      // Check if we have AWS credentials
      if (!process.env.AWS_REGION) {
        return false;
      }

      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION,
      });

      // List of secret names to fetch
      const secretNames = [
        process.env.APP_SECRETS_NAME || 'app/production/secrets',
        process.env.DB_SECRETS_NAME || 'app/production/database',
        process.env.API_SECRETS_NAME || 'app/production/api-keys'
      ];

      // Fetch all secrets in parallel
      const secretPromises = secretNames.map(async (secretName) => {
        try {
          const command = new GetSecretValueCommand({ SecretId: secretName });
          const response = await client.send(command);

          if (response.SecretString) {
            const secrets = JSON.parse(response.SecretString);
            Object.entries(secrets).forEach(([key, value]) => {
              this.secrets.set(key, value);
              // Also set as environment variable for compatibility
              if (!process.env[key]) {
                process.env[key] = value;
              }
            });
          }
        } catch (error) {
          console.warn(`⚠️  Failed to fetch secret ${secretName}:`, error.message);
        }
      });

      await Promise.all(secretPromises);
      return this.secrets.size > 0;

    } catch (error) {
      console.warn('⚠️  Cloud secrets manager not available:', error.message);
      return false;
    }
  }

  /**
   * Load secrets from environment variables
   */
  async loadFromEnvironment() {
    const requiredSecrets = [
      'ACCESS_TOKEN_SECRET',
      'REFRESH_TOKEN_SECRET',
      'DATABASE_URL',
      'NODE_ENV'
    ];

    // Check if all required secrets are in environment
    const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

    if (missingSecrets.length > 0 && process.env.NODE_ENV === 'production') {
      console.warn(`⚠️  Missing required secrets in environment: ${missingSecrets.join(', ')}`);
      return false;
    }

    // Copy all relevant environment variables to secrets map
    const envPrefixes = ['SECRET_', 'KEY_', 'TOKEN_', 'PASSWORD_', 'DATABASE_', 'AWS_'];

    Object.entries(process.env).forEach(([key, value]) => {
      if (envPrefixes.some(prefix => key.startsWith(prefix)) || 
          requiredSecrets.includes(key)) {
        this.secrets.set(key, value);
      }
    });

    return this.secrets.size > 0;
  }

  /**
   * Load secrets from local .env file (development only)
   */
  async loadFromEnvFile() {
    try {
      // Only allow in development or test environments
      if (process.env.NODE_ENV === 'production') {
        console.error('❌ Local .env files are not allowed in production');
        return false;
      }

      const envPath = process.env.ENV_FILE_PATH || '.env';
      const envContent = await fs.readFile(envPath, 'utf8');

      // Parse .env file
      envContent.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key) {
            const value = valueParts.join('=').replace(/^['"]|['"]$/g, '');
            this.secrets.set(key.trim(), value.trim());
            // Set as environment variable
            if (!process.env[key.trim()]) {
              process.env[key.trim()] = value.trim();
            }
          }
        }
      });

      return this.secrets.size > 0;

    } catch (error) {
      console.warn('⚠️  No .env file found:', error.message);
      return false;
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const requiredSecrets = {
      'ACCESS_TOKEN_SECRET': 'JWT access token signing secret',
      'REFRESH_TOKEN_SECRET': 'JWT refresh token signing secret',
      'NODE_ENV': 'Application environment',
    };

    const missingSecrets = [];
    const weakSecrets = [];

    for (const [secret, description] of Object.entries(requiredSecrets)) {
      const value = this.getSecret(secret);

      if (!value) {
        missingSecrets.push(`${secret} (${description})`);
      } else if (this.isWeakSecret(secret, value)) {
        weakSecrets.push(`${secret} (${description})`);
      }
    }

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    if (weakSecrets.length > 0) {
      console.warn(`⚠️  Weak secrets detected: ${weakSecrets.join(', ')}`);

      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Weak secrets in production: ${weakSecrets.join(', ')}`);
      }
    }
  }

  /**
   * Check if a secret value is weak/insecure
   */
  isWeakSecret(secretName, value) {
    // Check for common weak values
    const weakPatterns = [
      /^(password|secret|admin|test|123|changeme|default)$/i,
      /^fallback-/,
      /^CANARY-/,
      /^sk_test_/,
      /^REDACTED_STRIPE_LIVE/,
      /null|undefined|empty/i
    ];

    return weakPatterns.some(pattern => pattern.test(value));
  }

  /**
   * Get a secret by name
   */
  getSecret(name, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this.secrets.get(name) || process.env[name] || defaultValue;

    if (!value && defaultValue === null) {
      console.warn(`⚠️  Secret not found: ${name}`);
    }

    return value;
  }

  /**
   * Get all secrets (for debugging/logging - should redact sensitive values)
   */
  getAllSecrets(redact = true) {
    const secrets = {};

    this.secrets.forEach((value, key) => {
      if (redact && this.isSensitiveKey(key)) {
        secrets[key] = '***REDACTED***';
      } else {
        secrets[key] = value;
      }
    });

    return secrets;
  }

  /**
   * Check if a key contains sensitive information
   */
  isSensitiveKey(key) {
    const sensitivePatterns = [
      /SECRET$/i,
      /KEY$/i,
      /TOKEN$/i,
      /PASSWORD$/i,
      /PWD$/i,
      /PRIVATE$/i,
      /_SECRET_/i,
      /_KEY_/i,
      /_TOKEN_/i,
      /ACCESS_TOKEN/,
      /REFRESH_TOKEN/,
      /DATABASE_URL/,
      /AWS_SECRET_ACCESS_KEY/,
      /STRIPE_SECRET_KEY/
    ];

    return sensitivePatterns.some(pattern => pattern.test(key));
  }

  /**
   * Start watching for secret rotation (cloud secrets only)
   */
  startRotationWatchers() {
    // Implementation for AWS Secrets Manager rotation
    if (process.env.AWS_SECRETS_ROTATION_ENABLED === 'true') {
      console.log('🔄 Secret rotation watchers enabled');

      // Set up periodic checks for secret rotation
      // In production, use CloudWatch Events or similar
      const rotationCheckInterval = setInterval(async () => {
        await this.checkForRotations();
      }, 5 * 60 * 1000); // Check every 5 minutes

      this.rotationWatchers.set('rotation-check', rotationCheckInterval);
    }
  }

  /**
   * Check for rotated secrets
   */
  async checkForRotations() {
    try {
      // Implementation depends on cloud provider
      // AWS Secrets Manager has version tracking
      console.log('🔍 Checking for secret rotations...');
      // This would compare current versions with stored versions
    } catch (error) {
      console.error('Failed to check secret rotations:', error);
    }
  }

  /**
   * Clean up resources
   */
  async cleanup() {
    this.rotationWatchers.forEach((interval, name) => {
      clearInterval(interval);
      console.log(`🧹 Stopped ${name} watcher`);
    });
    this.rotationWatchers.clear();
  }
}

