// Simple secure secrets loader for smaller applications
// Provides secure secret loading without cloud dependencies

const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');

class SimpleSecretsLoader {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
    this.missingSecrets = [];
    this.weakSecrets = [];
  }

  /**
   * Initialize secrets with security checks
   */
  async initialize() {
    try {
      // 1. Load from environment variables (primary)
      this.loadFromEnvironment();

      // 2. Development: Load from .env file if needed
      if (process.env.NODE_ENV !== 'production') {
        await this.loadFromEnvFile('.env.development');
      }

      // 3. Validate all secrets
      this.validateSecrets();

      // 4. Apply security transformations
      this.enhanceSecrets();

      this.initialized = true;
      console.log(`✅ Secrets initialized (${this.secrets.size} loaded)`);

      // Report issues
      this.reportIssues();

    } catch (error) {
      console.error('❌ Failed to initialize secrets:', error.message);

      // In development, we can continue with warning
      if (process.env.NODE_ENV !== 'production') {
        console.warn('⚠️  Continuing with partial secrets (development only)');
        this.initialized = true;
      } else {
        throw error;
      }
    }
  }

  /**
   * Load secrets from environment variables
   */
  loadFromEnvironment() {
    const secretPatterns = [
      /SECRET$/i,
      /KEY$/i,
      /TOKEN$/i,
      /PASSWORD$/i,
      /DATABASE_/i,
      /JWT_/i,
      /ACCESS_TOKEN/i,
      /REFRESH_TOKEN/i,
      /AWS_/i,
      /STRIPE_/i,
      /API_KEY/i
    ];

    Object.entries(process.env).forEach(([key, value]) => {
      if (secretPatterns.some(pattern => pattern.test(key))) {
        this.secrets.set(key, value);
      }
    });

    // Always include these
    const required = ['NODE_ENV', 'PORT', 'HOST'];
    required.forEach(key => {
      if (process.env[key]) {
        this.secrets.set(key, process.env[key]);
      }
    });
  }

  /**
   * Load from .env file (development only)
   */
  async loadFromEnvFile(filePath = '.env') {
    if (process.env.NODE_ENV === 'production') {
      throw new Error(`Local .env files not allowed in production: ${filePath}`);
    }

    try {
      const content = await fs.readFile(filePath, 'utf8');

      content.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key) {
            const value = valueParts.join('=').replace(/^['"]|['"]$/g, '').trim();
            this.secrets.set(key.trim(), value);

            // Set as environment variable if not already set
            if (!process.env[key.trim()]) {
              process.env[key.trim()] = value;
            }
          }
        }
      });

    } catch (error) {
      if (process.env.NODE_ENV !== 'production') {
        console.warn(`⚠️  ${filePath} not found: ${error.message}`);
      } else {
        throw error;
      }
    }
  }

  /**
   * Validate all loaded secrets
   */
  validateSecrets() {
    const requiredSecrets = {
      'NODE_ENV': 'Application environment',
    };

    const productionRequired = {
      'ACCESS_TOKEN_SECRET': 'JWT signing secret',
      'DATABASE_URL': 'Database connection string',
    };

    // Check required secrets
    for (const [secret, description] of Object.entries(requiredSecrets)) {
      if (!this.secrets.get(secret)) {
        this.missingSecrets.push(`${secret} (${description})`);
      }
    }

    // Check production-specific requirements
    if (this.secrets.get('NODE_ENV') === 'production') {
      for (const [secret, description] of Object.entries(productionRequired)) {
        if (!this.secrets.get(secret)) {
          this.missingSecrets.push(`${secret} (${description})`);
        }
      }
    }

    // Check for weak secrets
    this.secrets.forEach((value, key) => {
      if (this.isWeakSecret(key, value)) {
        this.weakSecrets.push(key);
      }
    });

    // Fail if missing required secrets in production
    if (this.missingSecrets.length > 0 && this.secrets.get('NODE_ENV') === 'production') {
      throw new Error(`Missing required secrets: ${this.missingSecrets.join(', ')}`);
    }
  }

  /**
   * Check if a secret is weak/insecure
   */
  isWeakSecret(key, value) {
    if (!value) return false;

    const weakPatterns = [
      /^(password|secret|admin|test|123|changeme|default)$/i,
      /^fallback-/,
      /^CANARY-/,
      /^sk_test_/,
      /^REDACTED_STRIPE_LIVE/,
      /null|undefined|empty/i,
      /{.*}/, // JSON objects (might not be hashed/encrypted)
    ];

    // Check length for certain secrets
    if (key.includes('SECRET') || key.includes('KEY')) {
      if (value.length < 32) {
        return true; // Too short
      }
    }

    return weakPatterns.some(pattern => pattern.test(value));
  }

  /**
   * Enhance secrets with security features
   */
  enhanceSecrets() {
    // Generate missing JWT secret in development
    if (!this.secrets.get('ACCESS_TOKEN_SECRET') && process.env.NODE_ENV !== 'production') {
      const generatedSecret = crypto.randomBytes(32).toString('hex');
      this.secrets.set('ACCESS_TOKEN_SECRET', generatedSecret);
      console.warn('⚠️  Generated development JWT secret - CHANGE IN PRODUCTION');
    }

