// Secure Express.js application with security best practices

// Load environment variables
require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true
  }
}));

// 2. Custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.removeHeader('X-Powered-By');
  next();
});

// 3. CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com']
    : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET'],
  credentials: false, // Set to true if using sessions/cookies
  maxAge: 86400
};

app.use(cors(corsOptions));

// 4. Request body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP'
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many sensitive requests from this IP'
});

// 6. Security logging
const logDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir, { recursive: true });
}

const securityLogStream = fs.createWriteStream(
  path.join(logDir, 'security.log'),
  { flags: 'a' }
);

app.use(morgan('combined', { 
  stream: securityLogStream,
  skip: (req) => req.path === '/health' // Skip health checks
}));

// Security monitoring middleware
app.use((req, res, next) => {
  const suspiciousPatterns = [
    'sqlmap', 'nikto', 'dirbuster', 'wpscan', 'acunetix',
    '../', '..\\', 'etc/passwd', 'SELECT', 'INSERT', 'DELETE',
    'UPDATE', 'DROP', 'UNION', 'SCRIPT', 'JAVASCRIPT'
  ];

  const requestUrl = req.url.toLowerCase();
  const userAgent = req.headers['user-agent']?.toLowerCase() || '';

  for (const pattern of suspiciousPatterns) {
    if (requestUrl.includes(pattern) || userAgent.includes(pattern)) {
      securityLogStream.write(
        `[SECURITY ALERT] ${new Date().toISOString()} - ` +
        `Suspicious pattern detected: ${req.ip} - ` +
        `URL: ${req.url} - User-Agent: ${req.headers['user-agent']}\n`
      );
    }
  }

  next();
});

// ========== APPLICATION ENDPOINTS ==========

// Health endpoint with input validation
app.get('/health', generalLimiter, [
  query('debug').optional().isBoolean().toBoolean().withMessage('Debug must be boolean'),
  query('format').optional().isIn(['json', 'text']).withMessage('Format must be json or text')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array()
    });
  }

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    nodeVersion: process.version
  };

  // Sanitize output
  delete healthData.memory.external;

  res.json(healthData);
});

// Users endpoint with authentication and data masking
const mockAuthMiddleware = (req, res, next) => {
  // In production, use JWT or session-based authentication
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      error: 'Authentication required',
      code: 'AUTH_REQUIRED'
    });
  }

  const token = authHeader.substring(7);

  // Validate token (in real app, verify against your auth service)
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ 
      error: 'Invalid authentication token',
      code: 'INVALID_TOKEN'
    });
  }

  next();
};

app.get('/users', strictLimiter, mockAuthMiddleware, (req, res) => {
  // Validate query parameters
  const { limit = 10, offset = 0 } = req.query;

  const parsedLimit = parseInt(limit);
  const parsedOffset = parseInt(offset);

  if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
    return res.status(400).json({ error: 'Limit must be between 1 and 100' });
  }

  if (isNaN(parsedOffset) || parsedOffset < 0) {
    return res.status(400).json({ error: 'Offset must be non-negative' });
  }

  // Mock user data with PII masking
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: maskEmail('alice@example.com'),
      role: 'user',
      createdAt: '2024-01-01T00:00:00Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: maskEmail('bob@example.com'),
      role: 'admin',
      createdAt: '2024-01-02T00:00:00Z'
    }
  ];

  // Pagination simulation
  const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit: parsedLimit,
      offset: parsedOffset,
      hasMore: parsedOffset + parsedLimit < users.length
    }
  });
});

// Email masking utility
function maskEmail(email) {
  const [localPart, domain] = email.split('@');
  if (localPart.length <= 2) {
    return localPart.charAt(0) + '***@' + domain;
  }
  return localPart.charAt(0) + '***' + localPart.charAt(localPart.length - 1) + '@' + domain;
}

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Error handler
app.use((err, req, res, next) => {
  console.error('Application error:', err);
  securityLogStream.write(
    `[ERROR] ${new Date().toISOString()} - ` +
    `${err.message} - ${req.ip} - ${req.method} ${req.url}\n`
  );

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal server error',
    code: 'INTERNAL_ERROR',
    requestId: req.id || Date.now().toString(36)
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
    errorResponse.message = err.message;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER STARTUP ==========

// Validate environment variables
const requiredEnvVars = ['NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    console.error(`FATAL: Missing required environment variable: ${varName}`);
    process.exit(1);
  }
});

const port = process.env.PORT || 3000;
const host = process.env.HOST || 'localhost';

app.listen(port, host, () => {
  console.log(`Secure server running in ${process.env.NODE_ENV} mode`);
  console.log(`Listening on http://${host}:${port}`);

  // Security startup message
  securityLogStream.write(
    `[STARTUP] ${new Date().toISOString()} - ` +
    `Server started in ${process.env.NODE_ENV} mode on port ${port}\n`
  );
});

module.exports = app;

