// Advanced secrets management for production applications
// Use AWS Secrets Manager, Azure Key Vault, or HashiCorp Vault in production

const AWS = require('aws-sdk');
const cache = require('memory-cache');

class SecretsManager {
  constructor(options = {}) {
    this.options = {
      region: process.env.AWS_REGION || 'us-east-1',
      useCache: true,
      cacheTTL: 5 * 60 * 1000, // 5 minutes
      ...options
    };

    // In production, use AWS Secrets Manager
    if (process.env.NODE_ENV === 'production') {
      this.client = new AWS.SecretsManager({
        region: this.options.region
      });
    }

    // In development/test, use .env files (never commit these!)
    this.localSecrets = {};
  }

  /**
   * Get secret securely
   * @param {string} secretName - Name of the secret in secrets manager
   * @param {string} fallbackEnvVar - Environment variable fallback
   */
  async getSecret(secretName, fallbackEnvVar = null) {
    // Check cache first
    if (this.options.useCache) {
      const cached = cache.get(secretName);
      if (cached) return cached;
    }

    let secretValue;

    try {
      // Production: AWS Secrets Manager
      if (process.env.NODE_ENV === 'production' && this.client) {
        secretValue = await this.getFromAWS(secretName);
      }
      // Development: Local secrets manager (Docker, K8s, etc.)
      else if (process.env.SECRETS_FILE) {
        secretValue = await this.getFromFile(secretName);
      }
      // Fallback: Environment variable
      else if (fallbackEnvVar && process.env[fallbackEnvVar]) {
        secretValue = process.env[fallbackEnvVar];
        console.warn(`Using environment variable fallback for ${secretName}. Consider using secrets manager.`);
      }
      // Error
      else {
        throw new Error(`Secret ${secretName} not found and no fallback available`);
      }

      // Cache the result
      if (this.options.useCache && secretValue) {
        cache.put(secretName, secretValue, this.options.cacheTTL);
      }

      return secretValue;

    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);

      // In production, fail fast - don't use fallbacks
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Critical: Cannot retrieve production secret ${secretName}`);
      }

      // In development, allow fallback to mock values
      return this.getMockSecret(secretName);
    }
  }

  /**
   * Retrieve from AWS Secrets Manager
   */
  async getFromAWS(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        return buff.toString('ascii');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret ${secretName} not found in AWS Secrets Manager`);
      }
      throw error;
    }
  }

  /**
   * Retrieve from mounted secrets (K8s, Docker Swarm, etc.)
   */
  async getFromFile(secretName) {
    const fs = require('fs').promises;
    const path = require('path');

    const secretPath = path.join(process.env.SECRETS_FILE, secretName);

    try {
      const data = await fs.readFile(secretPath, 'utf8');
      return data.trim();
    } catch (error) {
      throw new Error(`Failed to read secret file ${secretPath}: ${error.message}`);
    }
  }

  /**
   * Get mock secret for development
   */
  getMockSecret(secretName) {
    // Return mock values for development
    const mockSecrets = {
      'database-password': 'dev_db_password',
      'api-key-anthropic': 'mock_anthropic_key_dev',
      'stripe-secret-key': 'REDACTED_STRIPE_TEST',
      'jwt-secret': 'dev_jwt_secret_change_in_production'
    };

    return mockSecrets[secretName] || `mock_${secretName}`;
  }

  /**
   * Rotate secret (for automated rotation)
   */
  async rotateSecret(secretName, newSecret) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('Secret rotation only supported in production');
      return;
    }

    try {
      // Create new version
      await this.client.updateSecret({
        SecretId: secretName,
        SecretString: JSON.stringify(newSecret)
      }).promise();

      console.log(`Secret ${secretName} rotated successfully`);

      // Clear cache
      cache.del(secretName);

    } catch (error) {
      console.error(`Failed to rotate secret ${secretName}:`, error);
      throw error;
    }
  }
}

// Example usage middleware
const secretsMiddleware = (secretConfig) => {
  const secretsManager = new SecretsManager();

  return async (req, res, next) => {
    try {
      // Load required secrets
      for (const [key, config] of Object.entries(secretConfig)) {
        req.secrets = req.secrets || {};
        req.secrets[key] = await secretsManager.getSecret(
          config.secretName,
          config.envVar
        );
      }

      next();
    } catch (error) {
      console.error('Failed to load secrets:', error);
      res.status(500).json({ 
        error: 'Configuration error',
        code: 'SECRETS_LOAD_FAILED'
      });
    }
  };
};

module.exports = {
  SecretsManager,
  secretsMiddleware
};

// Secure application bootstrap with proper secrets management
// DO NOT LOAD .env FILES IN PRODUCTION

const { SecretsManager } = require('./secrets-manager');

class SecureBootstrap {
  constructor() {
    this.secretsManager = new SecretsManager();
    this.config = {};
    this.secrets = {};
  }

  async initialize() {
    console.log('🔐 Initializing secure application...');

    try {
      // Step 1: Load minimal environment
      this.loadEnvironment();

      // Step 2: Validate critical configuration
      this.validateConfig();

      // Step 3: Load secrets from secure source
      await this.loadSecrets();

      // Step 4: Setup secure defaults
      this.setupSecureDefaults();

      // Step 5: Health check secrets
      await this.healthCheckSecrets();

      console.log('✅ Secure bootstrap completed');
      return {
        config: this.config,
        secrets: this.secrets
      };

    } catch (error) {
      console.error('❌ Bootstrap failed:', error.message);

      // Don't expose details in production
      if (process.env.NODE_ENV === 'production') {
        console.error('Critical configuration error. Application cannot start.');
        process.exit(1);
      }

      throw error;
    }
  }

  loadEnvironment() {
    // Only load .env in development mode
    if (process.env.NODE_ENV === 'development') {
      const dotenv = require('dotenv');

      // Determine which .env file to load
      const envFile = `.env.${process.env.NODE_ENV}`;

      try {
        const result = dotenv.config({ path: envFile });
        if (result.error) {
          console.warn(`Warning: Could not load ${envFile}: ${result.error.message}`);
        } else {
          console.log(`📁 Loaded environment from ${envFile}`);
        }
      } catch (error) {
        console.warn(`Warning: Failed to load ${envFile}: ${error.message}`);
      }
    } else {
      console.log('🔒 Skipping .env files in non-development environment');
    }

    // Set default configuration
    this.config = {
      // Application
      nodeEnv: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT || '3000'),
      host: process.env.HOST || 'localhost',

      // Security
      allowedOrigins: this.parseAllowedOrigins(),
      rateLimitEnabled: process.env.RATE_LIMIT_ENABLED !== 'false',

      // Features
      enableMetrics: process.env.ENABLE_METRICS === 'true',
      logLevel: process.env.LOG_LEVEL || 'info'
    };
  }

  parseAllowedOrigins() {
    const origins = process.env.ALLOWED_ORIGINS;
    if (!origins) {
      return this.config.nodeEnv === 'production'
        ? []
        : ['http://localhost:3000', 'http://localhost:8080'];
    }
    return origins.split(',').map(origin => origin.trim());
  }

  validateConfig() {
    const errors = [];

    // Validate port
    if (this.config.port < 1 || this.config.port > 65535) {
      errors.push(`Invalid port: ${this.config.port}`);
    }

    // Production checks
    if (this.config.nodeEnv === 'production') {
      if (this.config.allowedOrigins.length === 0) {
        errors.push('ALLOWED_ORIGINS must be set in production');
      }

      // Warn about suspicious configurations
      if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('localhost')) {
        console.warn('⚠️ Warning: Production DATABASE_URL contains localhost');
      }

      if (process.env.AWS_ACCESS_KEY_ID) {
        console.warn('⚠️ Warning: AWS_ACCESS_KEY_ID in environment variables. Use IAM roles instead.');
      }
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }
  }

  async loadSecrets() {
    console.log('🔑 Loading secrets...');

    const secretDefinitions = {
      // Database connection
      database: {
        secretName: 'app/database/production',
        envVar: 'DATABASE_URL',
        required: true
      },

      // API Keys
      anthropicApiKey: {
        secretName: 'app/api-keys/anthropic',
        envVar: 'ANTHROPIC_API_KEY',
        required: this.config.nodeEnv === 'production'
      },

      stripeSecretKey: {
        secretName: 'app/api-keys/stripe',
        envVar: 'STRIPE_SECRET_KEY',
        required: false
      },

      // JWT Secrets
      jwtSecret: {
        secretName: 'app/jwt/secret',
        envVar: 'JWT_SECRET',
        required: true
      },

      // Encryption keys
      encryptionKey: {
        secretName: 'app/encryption/key',
        envVar: 'ENCRYPTION_KEY',
        required: true
      }
    };

    for (const [key, definition] of Object.entries(secretDefinitions)) {
      try {
        const value = await this.secretsManager.getSecret(
          definition.secretName,
          definition.envVar
        );

        if (definition.required && !value) {
          throw new Error(`Required secret ${key} not found`);
        }

        this.secrets[key] = value;

        // Log (but mask secrets)
        if (value) {
          const maskedValue = this.maskSecret(value);
          console.log(`   ${key}: ${maskedValue}`);
        }

      } catch (error) {
        if (definition.required) {
          throw new Error(`Failed to load required secret ${key}: ${error.message}`);
        }
        console.warn(`   ${key}: Not loaded (${error.message})`);
      }
    }

    console.log(`✅ Loaded ${Object.keys(this.secrets).length} secrets`);
  }

  maskSecret(secret) {
    if (!secret || typeof secret !== 'string') return '[NOT_A_STRING]';
    if (secret.length <= 8) return '***';

    // Show first 3 and last 3 characters, mask the rest
    const firstPart = secret.substring(0, 3);
    const lastPart = secret.substring(secret.length - 3);
    const middleLength = secret.length - 6;

    return `${firstPart}${'*'.repeat(Math.min(middleLength, 6))}${lastPart}`;
  }

  setupSecureDefaults() {
    // Disable verbose logging in production
    if (this.config.nodeEnv === 'production') {
      process.env.DEBUG = '';
    }

    // Set memory limits
    if (process.env.NODE_MEMORY_LIMIT) {
      const memoryLimit = parseInt(process.env.NODE_MEMORY_LIMIT);
      if (!isNaN(memoryLimit)) {
        const v8 = require('v8');
        v8.setFlagsFromString(`--max-old-space-size=${memoryLimit}`);
      }
    }
  }

  async healthCheckSecrets() {
    if (this.config.nodeEnv !== 'production') {
      return; // Skip in development
    }

    console.log('🏥 Performing secret health checks...');

    const checks = [];

    // Check database connectivity
    if (this.secrets.database) {
      checks.push(this.testDatabaseConnection());
    }

    // Check API key validity (if applicable)
    if (this.secrets.anthropicApiKey) {
      checks.push(this.testApiKey('anthropic'));
    }

    // Wait for all checks
    const results = await Promise.allSettled(checks);

    const failures = results.filter(r => r.status === 'rejected');
    if (failures.length > 0) {
      console.warn(`⚠️ ${failures.length} secret health checks failed:`);
      failures.forEach(f => console.warn(`   ${f.reason.message}`));
    }
  }

  async testDatabaseConnection() {
    // Implementation depends on database driver
    return Promise.resolve();
  }

  async testApiKey(provider) {
    // Implementation depends on provider
    return Promise.resolve();
  }

  /**
   * Generate security report
   */
  generateSecurityReport() {
    return {
      timestamp: new Date().toISOString(),
      environment: this.config.nodeEnv,
      security: {
        secretsLoaded: Object.keys(this.secrets).length,
        usingSecureStore: process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : 'Local files',
        hasDatabaseSecret: !!this.secrets.database,
        hasJwtSecret: !!this.secrets.jwtSecret,
        hasEncryptionKey: !!this.secrets.encryptionKey
      },
      warnings: this.getSecurityWarnings()
    };
  }

  getSecurityWarnings() {
    const warnings = [];

    // Development mode warnings
    if (this.config.nodeEnv === 'development') {
      if (this.secrets.database && this.secrets.database.includes('production')) {
        warnings.push('Development environment using production database');
      }
    }

    // Secret length warnings
    if (this.secrets.jwtSecret && this.secrets.jwtSecret.length < 32) {
      warnings.push('JWT secret is too short (minimum 32 characters recommended)');
    }

    // Pattern warnings
    for (const [key, value] of Object.entries(this.secrets)) {
      if (typeof value === 'string') {
        if (value.toLowerCase().includes('password') || value.toLowerCase().includes('secret')) {
          warnings.push(`Secret ${key} may contain default/hardcoded value`);
        }
      }
    }

    return warnings;
  }
}

// Export singleton instance
const bootstrap = new SecureBootstrap();
module.exports = bootstrap;

// Production-ready application with secure secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

// ========== SECRETS MANAGEMENT ==========

// Production secrets should NEVER be loaded from .env files
// Use environment variables injected at runtime OR secrets manager

class Secrets {
  static validate() {
    const requiredSecrets = [
      'JWT_SECRET',
      'ENCRYPTION_KEY'
    ];

    const missing = [];

    for (const secret of requiredSecrets) {
      if (!process.env[secret]) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate secret strength
    this.validateStrength();

    return true;
  }

  static validateStrength() {
    // JWT secret should be at least 32 characters
    if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
      console.warn('⚠️ WARNING: JWT_SECRET is less than 32 characters');
    }

    // Check for default/weak values
    const weakPatterns = [
      'secret', 'password', 'changeme', 'default',
      '123456', 'admin', 'test'
    ];

    for (const [key, value] of Object.entries(process.env)) {
      if (value && typeof value === 'string') {
        for (const pattern of weakPatterns) {
          if (value.toLowerCase().includes(pattern)) {
            console.warn(`⚠️ WARNING: ${key} may contain weak/default value`);
            break;
          }
        }
      }
    }
  }

  static getDatabaseConfig() {
    // In production, use IAM authentication or connection strings from secrets manager
    if (process.env.NODE_ENV === 'production') {
      return {
        host: process.env.DB_HOST,
        port: process.env.DB_PORT || 5432,
        database: process.env.DB_NAME,
        // Password should come from IAM role or secrets manager
        password: process.env.DB_PASSWORD
      };
    }

    // Development: Use local config
    return {
      host: 'localhost',
      port: 5432,
      database: 'app_dev',
      password: 'dev_password' // Use different password for each environment
    };
  }
}

// ========== APPLICATION SETUP ==========

const app = express();

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'"],
      scriptSrc: ["'self'"]
    }
  }
}));

// CORS - strict in production
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',')
      : [];

    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (process.env.NODE_ENV === 'development') {
      // Allow all in development for easier testing
      return callback(null, true);
    }

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      console.warn(`CORS blocked: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// JSON parsing with limits
app.use(express.json({ limit: '1mb' }));

// ========== SECURE MIDDLEWARE ==========

// Request validation middleware
app.use((req, res, next) => {
  // Reject requests with suspicious content types
  const contentType = req.headers['content-type'] || '';
  const allowedTypes = ['application/json', 'application/x-www-form-urlencoded'];

  if (req.method === 'POST' || req.method === 'PUT') {
    if (contentType && !allowedTypes.some(type => contentType.includes(type))) {
      return res.status(415).json({ error: 'Unsupported media type' });
    }
  }

  next();
});

// Security audit logging
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;

    // Log security-sensitive requests
    if (req.path.includes('/admin') || req.path.includes('/api/')) {
      console.log(`[SECURITY] ${new Date().toISOString()} ${req.ip} ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
    }

    // Alert on slow requests (potential DoS)
    if (duration > 5000) {
      console.warn(`[PERF] Slow request: ${req.method} ${req.path} took ${duration}ms`);
    }
  });

  next();
});

// ========== ROUTES ==========

// Health endpoint - no secrets exposed
app.get('/health', (req, res) => {
  const health = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    // DO NOT expose secret information
    features: {
      database: !!process.env.DB_HOST,
      auth: !!process.env.JWT_SECRET
    }
  };

  res.json(health);
});

// Protected endpoint example
app.get('/secure/data', (req, res) => {
  // Validate authorization
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authorization required' });
  }

  const token = authHeader.substring(7);

  // In production, use a proper JWT library with the secret from environment
  try {
    // This is a mock - use jsonwebtoken library in production
    const isValid = token === process.env.API_TOKEN;

    if (!isValid) {
      return res.status(403).json({ error: 'Invalid token' });
    }

    res.json({
      data: 'This is secure data',
      accessedAt: new Date().toISOString()
    });

  } catch (error) {
    console.error('Token validation error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ========== ERROR HANDLING ==========

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  console.error('Application error:', err);

  // Don't expose error details in production
  const response = {
    error: 'Internal server error',
    requestId: Date.now().toString(36)
  };

  if (process.env.NODE_ENV !== 'production') {
    response.message = err.message;
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// ========== STARTUP ==========

async function startServer() {
  try {
    console.log('🔒 Starting secure application...');

    // Validate secrets before starting
    Secrets.validate();

    const port = process.env.PORT || 3000;

    app.listen(port, () => {
      console.log(`✅ Secure server running on port ${port}`);
      console.log(`   Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`   Origins allowed: ${process.env.ALLOWED_ORIGINS || 'Development mode (all)'}`);

      // Security startup checklist
      console.log('\n🔐 Security Status:');
      console.log(`   ✓ Helmet security headers enabled`);
      console.log(`   ✓ CORS configured: ${process.env.ALLOWED_ORIGINS ? 'Restricted' : 'Development mode'}`);
      console.log(`   ✓ Secrets validated: ${Object.keys(process.env).filter(k => k.includes('SECRET') || k.includes('KEY')).length} found`);
      console.log(`   ✓ Request size limits: 1MB`);

      if (process.env.NODE_ENV === 'production') {
        console.log('\n⚠️  PRODUCTION WARNINGS:');
        if (process.env.DATABASE_URL) {
          console.log('   ⚠️  DATABASE_URL in environment - consider using IAM roles');
        }
        if (process.env.AWS_ACCESS_KEY_ID) {
          console.log('   ⚠️  AWS_ACCESS_KEY_ID in environment - use instance profiles');
        }
      }
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
}

// Only start if this file is the main module
if (require.main === module) {
  startServer();
}

module.exports = {
