#### **3. Implement Secure Secrets Loading Pattern**
```javascript
// secrets-loader.js
const crypto = require('crypto');

class SecureSecretsLoader {
  constructor() {
    this.secrets = new Map();
    this.encryptionKey = process.env.SECRETS_ENCRYPTION_KEY;
  }

  // Load secrets from secure source
  async loadSecrets() {
    const source = process.env.SECRETS_SOURCE || 'vault';

    switch (source) {
      case 'vault':
        return await this.loadFromVault();
      case 'aws-sm':
        return await this.loadFromAWSSecretsManager();
      case 'azure-kv':
        return await this.loadFromAzureKeyVault();
      case 'local-encrypted':
        return await this.loadFromEncryptedFile();
      default:
        throw new Error(`Unsupported secrets source: ${source}`);
    }
  }

  async loadFromEncryptedFile() {
    // For development only - encrypted local file
    const fs = require('fs').promises;
    const encryptedData = await fs.readFile('.secrets.enc', 'utf8');

    const decipher = crypto.createDecipheriv(
      'aes-256-gcm',
      Buffer.from(this.encryptionKey, 'hex'),
      Buffer.from(encryptedData.slice(0, 24), 'hex')
    );

    let decrypted = decipher.update(encryptedData.slice(24), 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return JSON.parse(decrypted);
  }

  getSecret(key) {
    if (!this.secrets.has(key)) {
      throw new Error(`Secret ${key} not loaded`);
    }
    return this.secrets.get(key);
  }
}
