// Secure Express.js application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config(); // Load environment variables

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: false })); // Parse URL-encoded bodies

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter); // Apply to API routes

// CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : '*', // In development, allow all origins
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: process.env.NODE_ENV === 'production',
};

app.use(cors(corsOptions));

// Authentication middleware example
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Access token required' });

  // In production, verify with JWT or your auth service
  // For demo purposes, simple token check
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  req.user = { id: 1 }; // Mock user after authentication
  next();
};

// Health endpoint (minimal information disclosure)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    uptime: process.uptime() // Less sensitive than exact timestamp
  });
});

// Users endpoint with authentication and validation
app.get('/users', authenticateToken, (req, res) => {
  // Always sanitize output
  res.json([
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com' 
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com' 
    },
  ]);
});

// Example POST endpoint with full validation
app.post('/users', [
  // Input validation
  body('email').isEmail().normalizeEmail().withMessage('Valid email required'),
  body('name').trim().escape().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
], (req, res) => {
  // Check validation results
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Process validated data
  const { email, name } = req.body;

  res.status(201).json({
    message: 'User created successfully',
    user: { email, name }
  });
});

// Centralized error handling
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(err.status || 500).json({
    error: message,
    path: req.path,
    method: req.method
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.originalUrl
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

