    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  };

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}` 
  });
});

// Get port from environment variable
const PORT = process.env.PORT || 3000;

app.listen(PORT, async () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

  // Initialize secrets manager on startup
  try {
    await secretsManager.initialize();
    console.log('Secrets manager initialized');
  } catch (error) {
    console.error('Failed to initialize secrets manager:', error.message);
    console.error('Application continues without secrets manager (not recommended for production)');
  }
});

module.exports = app;

