#!/usr/bin/env node

/**
 * Security check script
 * Run this script to check for security issues in the project
 */

const fs = require('fs');
const path = require('path');

// Patterns that indicate potential security issues
const SECURITY_PATTERNS = {
  // Hardcoded credentials patterns
  hardcodedCredentials: [
    /password\s*[:=]\s*['"][^'"]+['"]/gi,
    /secret\s*[:=]\s*['"][^'"]+['"]/gi,
    /api[_-]?key\s*[:=]\s*['"][^'"]+['"]/gi,
    /token\s*[:=]\s*['"][^'"]+['"]/gi,
    /aws[_-]?access[_-]?key[_-]?id\s*[:=]\s*['"][^'"]+['"]/gi,
    /aws[_-]?secret[_-]?access[_-]?key\s*[:=]\s*['"][^'"]+['"]/gi,
    /database[_-]?url\s*[:=]\s*['"][^'"]+['"]/gi,
    /mongodb[:\/\/][^'"\s]+/gi,
    /postgres[:\/\/][^'"\s]+/gi,
    /mysql[:\/\/][^'"\s]+/gi,
  ],

  // Dangerous patterns
  dangerousPatterns: [
    /eval\s*\(/gi,
    /Function\s*\(/gi,
    /setTimeout\s*\([^)]*['"][^)]*['"]/gi,
    /setInterval\s*\([^)]*['"][^)]*['"]/gi,
    /innerHTML\s*=/gi,
    /outerHTML\s*=/gi,
    /document\.write/gi,
    /require\s*\([^)]*['"][^)]*['"]/gi,  // Dynamic requires
  ],

  // Environment file checks
  envPatterns: [
    /\.env[^.]/gi,  // .env files but not .env.example
  ]
};

// Files to exclude from security checks
const EXCLUDED_FILES = [
  'node_modules',
  '.git',
  '.env.example',
  '.gitignore',
  'README.md',
  'check-security.js'  // Exclude self
];

// Colors for console output
const colors = {
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  green: '\x1b[32m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m'
};

/**
 * Check if a file should be excluded
 */
function shouldExcludeFile(filePath) {
  return EXCLUDED_FILES.some(excluded => 
    filePath.includes(excluded) || 
    path.basename(filePath).startsWith('.env') && !filePath.includes('.env.example')
  );
}

/**
 * Scan a file for security issues
 */
function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const issues = [];

    // Check each pattern category
    Object.entries(SECURITY_PATTERNS).forEach(([category, patterns]) => {
      patterns.forEach(pattern => {
        const matches = content.match(pattern);
        if (matches) {
          matches.forEach(match => {
            // Find line number
            const lines = content.split('\n');
            let lineNumber = 1;
            for (let i = 0; i < lines.length; i++) {
              if (lines[i].includes(match)) {
                lineNumber = i + 1;
                break;
              }
            }

            issues.push({
              category,
              pattern: pattern.toString(),
              match: match.substring(0, 100), // Truncate long matches
              line: lineNumber,
              file: filePath
            });
          });
        }
      });
    });

    return issues;
  } catch (error) {
    console.error(`${colors.red}Error reading file ${filePath}: ${error.message}${colors.reset}`);
    return [];
  }
}

/**
 * Scan all files in directory recursively
 */
function scanDirectory(dir) {
  const results = {
    filesScanned: 0,
    issuesFound: 0,
    issuesByCategory: {},
    details: []
  };

  function walk(currentPath) {
    const files = fs.readdirSync(currentPath);

    files.forEach(file => {
      const fullPath = path.join(currentPath, file);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        if (!shouldExcludeFile(fullPath)) {
          walk(fullPath);
        }
      } else if (stat.isFile()) {
        if (!shouldExcludeFile(fullPath)) {
          results.filesScanned++;
          const issues = scanFile(fullPath);

          if (issues.length > 0) {
            results.issuesFound += issues.length;
            issues.forEach(issue => {
              if (!results.issuesByCategory[issue.category]) {
                results.issuesByCategory[issue.category] = 0;
              }
              results.issuesByCategory[issue.category]++;
              results.details.push(issue);
            });
          }
        }
      }
    });
  }

  walk(dir);
  return results;
}

/**
 * Main function
 */
function main() {
  console.log(`${colors.cyan}🔒 Security Scanner Starting...${colors.reset}`);
  console.log(`${colors.blue}Scanning directory: ${process.cwd()}${colors.reset}\n`);

  const results = scanDirectory(process.cwd());

  // Print summary
  console.log(`${colors.cyan}📊 Scan Results:${colors.reset}`);
  console.log(`${colors.blue}Files scanned: ${results.filesScanned}${colors.reset}`);
  console.log(`${colors.blue}Total issues found: ${results.issuesFound}${colors.reset}\n`);

  // Print issues by category
  if (Object.keys(results.issuesByCategory).length > 0) {
    console.log(`${colors.yellow}⚠️  Issues by Category:${colors.reset}`);
    Object.entries(results.issuesByCategory).forEach(([category, count]) => {
      console.log(`${colors.yellow}  ${category}: ${count} issues${colors.reset}`);
    });
    console.log('');
  }

  // Print detailed issues
  if (results.details.length > 0) {
    console.log(`${colors.red}🔴 Detailed Issues:${colors.reset}`);
    results.details.forEach((issue, index) => {
      console.log(`${colors.red}[${index + 1}] ${issue.category}${colors.reset}`);
      console.log(`   File: ${issue.file}`);
      console.log(`   Line: ${issue.line}`);
      console.log(`   Match: ${issue.match}`);
      console.log('');
    });
  }

  // Check for .env files
  const envFiles = fs.readdirSync(process.cwd())
    .filter(file => file.startsWith('.env') && file !== '.env.example');

  if (envFiles.length > 0) {
    console.log(`${colors.yellow}⚠️  Warning: Found .env files (exclude from version control):${colors.reset}`);
    envFiles.forEach(file => {
      console.log(`${colors.yellow}  - ${file}${colors.reset}`);
    });
    console.log('');
  }

  // Final verdict
  if (results.issuesFound === 0 && envFiles.length === 0) {
    console.log(`${colors.green}✅ No security issues found!${colors.reset}`);
  } else if (results.issuesFound > 0) {
    console.log(`${colors.red}❌ Security issues found. Review and fix them.${colors.reset}`);
    process.exit(1);
  } else {
    console.log(`${colors.green}✅ Code is clean, but check .env files.${colors.reset}`);
  }
}

// Run the scanner
if (require.main === module) {
  main();
}

module.exports = { scanDirectory, SECURITY_PATTERNS };

